diff --git a/src/store.ts b/src/store.ts
index bf9310a..5c677c5 100644
--- a/src/store.ts
+++ b/src/store.ts
@@ -9,8 +9,9 @@ export interface Row<T> {

 const rows = new Map<string, Row<unknown>>();

-export function put<T>(id: string, value: T): Row<T> {
+export function put<T>(id: string, value: T): Row<T> | null {
   const row: Row<T> = { id, value, updatedAt: Date.now() };
+  if (rows.size >= 10000 && !rows.has(id)) return null;
   rows.set(id, row as Row<unknown>);
   return row;
 }
